import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-simple-approval-bpmn/ExpenseApprovalBpmn/ExpenseApprovalBpmn.bpmn')
print('XML well-formed: OK')
root = tree.getroot()
ns_bpmn='http://www.omg.org/spec/BPMN/20100524/MODEL'

# Collect all bpmn element ids (not uipath bindings)
all_ids = {e.get('id') for e in root.iter() if e.get('id') and e.tag.startswith('{http://www.omg.org/spec/BPMN')}

flows = [e for e in root.iter(f'{{{ns_bpmn}}}sequenceFlow')]

# Check exclusive gateways
errors = []
for gw in root.iter(f'{{{ns_bpmn}}}exclusiveGateway'):
    outgoing = [c.text.strip() for c in gw if c.tag.endswith('}outgoing')]
    default = gw.get('default')
    incoming = [c.text.strip() for c in gw if c.tag.endswith('}incoming')]
    print(f'XOR gw {gw.get(\"id\")}: incoming={len(incoming)} outgoing={len(outgoing)} default={default}')
    if len(outgoing) > 1 and not default:
        errors.append(f'  ERROR: no default on {gw.get(\"id\")}')
    for fid in outgoing:
        if fid == default:
            continue
        for flow in flows:
            if flow.get('id') == fid:
                cond = flow.find(f'{{{ns_bpmn}}}conditionExpression')
                if cond is None:
                    errors.append(f'  ERROR: non-default flow {fid} missing conditionExpression on gw {gw.get(\"id\")}')

# Check no activity has multiple incoming flows
for e in root.iter():
    if e.tag in [f'{{{ns_bpmn}}}{t}' for t in ('serviceTask','sendTask','scriptTask','userTask','endEvent')]:
        inc = [c for c in e if c.tag.endswith('}incoming')]
        if len(inc) > 1:
            errors.append(f'  ERROR: {e.tag} {e.get(\"id\")} has {len(inc)} incoming flows (FAKE_JOIN)')

if errors:
    for e in errors: print(e)
else:
    print('All gateway checks passed')
"
